def render(data,root,out):
 css=(root/'scripts/editorial.css').read_text();js=(root/'scripts/editorial.js').read_text()
 items=[i for i in data['items'] if not i.get('placeholder') and i.get('status')=='published'];byid={i['id']:i for i in items}
 cats=sorted(data['categories'],key=lambda c:c.get('order',0));labels={c['id']:c for c in cats}
 latest=max(i.get('date','') for i in items)
 def tr(tag,zh,en,attrs=''):
  return f'<{tag} data-zh="{e(zh,quote=True)}" data-en="{e(en,quote=True)}" {attrs}>{e(zh)}</{tag}>'
 def img(i):return '/'+str(next((out/'assets/thumbs').glob('article-'+i['id']+'-*.webp')).relative_to(out))
 def cover_sources(item):
  chinese = img(item)
  english = f'/assets/covers-en/{item["id"]}.webp'
  return f'src="{chinese}" data-image-zh="{chinese}" data-image-en="{english}"'

 def link(ident):return '/posts/'+ident+'.html'
 nav=''.join(tr('a',zh,en,f'href="#{ident}"') for ident,zh,en in [('work','做过的事','Work'),('writing','手记','Notes'),('now','此刻','Now'),('about','关于','About'),('contact','联系','Contact')])
 filters=tr('button','全部手记','All notes','type="button" data-filter="all" aria-pressed="true"')
 for c in cats:
  count=sum(i['category']==c['id'] for i in items)
  filters+=f'<button type="button" data-filter="{c["id"]}" aria-pressed="false"><span><i class="seed" aria-hidden="true"></i>{tr("span",c["zh"],c["en"])}</span><b>{count:02d}</b></button>'
 # Provide all content in HTML. JavaScript progressively shows the first six.
 entries=[]
 for i in items:
  cat=labels[i['category']];minutes=max(1,(len(i['body']['zh'])+449)//450)
  keywords=' '.join([i['title']['zh'],i['title']['en'],i['summary']['zh'],cat['zh']])
  entries.append(f'<a class="article-row" href="{link(i["id"])}" data-category="{i["category"]}" data-id="{i["id"]}" data-search="{e(keywords,quote=True)}"><img {cover_sources(i)} width="480" height="320" loading="lazy" decoding="async" alt=""><div class="entry-line">{tr("span",cat["zh"],cat["en"],"class=\"cat\"")}<time datetime="{i.get("date","")}">{i.get("date","").replace("-",".")}</time>{tr("span",f"约 {minutes} 分钟",f"{minutes} min read","class=\"reading-time\"")}</div>{tr("h3",i["title"]["zh"],i["title"]["en"])}{tr("p",i["summary"]["zh"],i["summary"]["en"],"class=\"row-summary\"")}<span class="row-arrow" aria-hidden="true">↗</span></a>')
 project_notes=[]
 specs=[('parallel-universe','平行宇宙报社','Parallel Universe Press','创作实验 / 与 AI 协作','CREATIVE / WITH AI','把一个“25 小时世界”的设定，做成可以阅读、搜索和收藏的报纸。','A fictional 25-hour world, made into a newspaper you can read, search and save.'),('vps-review','两台 VPS 的折腾记录','Learning to care for two VPSs','部署与维护 / 过程记录','SERVERS / FIELD NOTES','从开通到连接、线路、备份与维护，把遇到的问题逐个记下来。','Notes on setup, connectivity, backups and the less glamorous work of maintenance.'),('website-build','这座不断改版的小站','This ever-changing little site','个人网站 / 迭代记录','WEB / ITERATIONS','关于网页怎样从“能打开”，走到手机上也愿意读。','From a page that loads to a place worth reading on a phone.')]
 for ident,zh,en,kz,ke,desc,descen in specs:
  i=byid[ident]
  project_notes.append(f'<a class="project-note" href="{link(ident)}"><img {cover_sources(i)} width="83" height="66" loading="lazy" decoding="async" alt=""><div>{tr("span",kz,ke,"class=\"small-label\"")}{tr("h3",zh,en)}{tr("p",desc,descen)}</div><span class="arrow" aria-hidden="true">↗</span></a>')
 routes=''.join(f'<a class="route" href="#{ident}"><span class="route-icon" aria-hidden="true">{icon}</span><span>{tr("strong",zh,en)}{tr("small",desc,de)}</span><span class="arrow" aria-hidden="true">↗</span></a>' for ident,icon,zh,en,desc,de in [('work','⌁','想看我做过什么','See what I have made','从项目和过程记录开始','Projects and the process behind them'),('writing','▤','想读点最近的想法','Read a few field notes','工程、AI 和生活，按兴趣逛','Engineering, AI, and everyday life'),('about','✳','想认识一下我','Get to know me','一个还在边学边做的人','Learning by doing, and still figuring it out')])
 q=byid['a-share-quant-research']
 html=f'''<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#f6f4ed"><meta name="description" content="{e(data['site']['description']['zh'])}"><title>Young 的手记 · 在工程与好奇心之间</title><link rel="canonical" href="https://young7788-web.github.io/"><link rel="icon" href="/favicon.svg" type="image/svg+xml"><link rel="alternate" type="application/rss+xml" title="Young 的数字花园" href="https://young7788-web.github.io/feed.xml"><style>{css}</style></head><body><a class="skip" href="#main">跳到正文</a><header class="top"><div class="shell top-inner"><a class="brand" href="#home" aria-label="Young 首页"><span class="brand-mark" aria-hidden="true">y</span>Young{tr('small','的数字花园',' / Digital Garden')}</a><nav class="nav" id="mainnav" aria-label="主导航">{nav}</nav><div class="utility"><button id="language" type="button" aria-label="切换中英文">EN / 中</button><button id="theme" type="button" class="theme" aria-label="切换深浅主题" aria-pressed="false">☾ 夜读</button><button id="menu" type="button" class="menu" aria-label="展开导航" aria-controls="mainnav" aria-expanded="false">☰</button></div></div></header><main class="shell" id="main">
<section class="hero" id="home"><div><p class="eyebrow">A NOTEBOOK FOR THE CURIOUS</p>{tr('p','你好，我是 Young。','Hello, I am Young.','class="intro"')}<h1>{tr('span','把好奇心，','Turning curiosity')}{tr('span','变成做过的事。','into things I make.','class="under"')}</h1>{tr('p','在北方某本科高校读电气工程及其自动化。学专业课，也折腾 AI、网站和服务器；把做过的事、没想通的问题，还有生活里的小片段，都留在这里。','An electrical engineering student at a university in northern China. I tinker with AI, websites and servers, and keep notes on what I make, what puzzles me, and everyday life.','class="hero-description"')}<div class="hero-actions"><a class="button" href="#work">{tr('span','看看做过的事','Explore my work')}<span aria-hidden="true">↗</span></a><a class="text-link" href="#writing">{tr('span','翻翻我的手记','Browse the notes')}<span aria-hidden="true">↓</span></a></div><div class="hero-foot"><span><i aria-hidden="true"></i>{tr('span','边学边做，持续记录','Learning by doing')}</span><span>ENGINEERING · AI · LIFE</span></div></div><aside class="desk" aria-label="好奇心工作台插画"><div class="desk-top"><span class="small-label">YOUNG'S WORKBENCH / 好奇心工作台</span><span class="desk-stamp">FIELD NOTES</span></div>{DESK}<div class="desk-caption">{tr('span','课本之外，也想亲手试试。','Beyond the textbook, try it yourself.')}<a href="#lab">{tr('span','桌上有个小实验','Try the small experiment')} ↗</a></div></aside></section>
<div class="routes" aria-label="从这里开始">{routes}</div>
<section class="section" id="work"><span class="section-alias" id="explore" aria-hidden="true"></span><div class="section-head"><div><span class="label">01 / SELECTED WORK</span>{tr('h2','把过程也留下来。','Keep the process, too.')}</div><a class="more" href="#writing" data-group="making">{tr('span','更多动手记录','More making notes')} ↗</a></div><div class="work-grid"><a class="feature-work" href="{link(q['id'])}"><div class="feature-picture"><img {cover_sources(q)} width="480" height="320" loading="lazy" decoding="async" alt=""><span class="feature-tag">RESEARCH JOURNAL / 研究记录</span></div><div class="feature-copy">{tr('span','01 · 规则 / 数据 / 回测','01 · RULES / DATA / BACKTESTS','class="small-label"')}{tr('h3','先核对数据，再相信回测。','Check the data before trusting the backtest.')}{tr('p','一次 A 股量化研究的过程记录：和 AI 一起整理规则，检查数据与假设，再复盘那些没有按愿望发展的结果。','A record of researching A-share strategies with AI: making rules explicit, checking data and assumptions, and reviewing results that did not follow the plan.')}<div class="project-foot">{tr('span','规则整理 · 数据核对 · 虚拟回测','Rules · Data checks · Simulated backtests','class="role"')}{tr('span','读研究过程 ↗','Read the process ↗')}</div></div></a><div class="project-stack">{''.join(project_notes)}</div></div>{tr('p','每个入口都通向过程记录：做了什么、卡在哪里、后来怎么改。','Each link leads to the process: what I tried, what went wrong, and what changed.','class="work-note"')}</section>
<section class="section" id="writing"><span id="collection" class="section-alias" aria-hidden="true"></span><div class="section-head"><div><span class="label">02 / NOTES FROM THE GARDEN</span>{tr('h2','最近写下的几页。','A few recent pages.')}</div><a class="more" href="/lite.html">{tr('span','纯文字目录','Text-only index')} ↗</a></div><div class="writing-area"><div><label class="searchbox"><span aria-hidden="true">⌕</span><input type="search" id="search" aria-label="搜索文章标题及摘要" placeholder="找一篇手记，或一个你也好奇的问题…"></label><div class="list-meta">{tr('span','记录真实做过、想过的事','Things I have actually done and thought about')}<div class="view-switch" role="group" aria-label="文章展示方式"><button type="button" data-view="list" aria-pressed="true">{tr('span','手记','List')}</button><button type="button" data-view="archive" aria-pressed="false">{tr('span','封面','Covers')}</button></div></div><div class="article-list" id="article-list">{''.join(entries)}</div>{tr('p','没有找到这篇手记，换个词试试。','No matching notes. Try another word.','class="empty" id="empty" hidden')}<button class="load-more" type="button" id="load-more" aria-controls="article-list" aria-expanded="false" hidden>展开全部记录 ↓</button><p class="count" id="result-count" aria-live="polite">{len(items)} 篇公开记录</p></div><aside class="reading-sidebar"><div class="garden-map"><h3 class="sidebar-title">{tr('span','沿着兴趣逛逛','Follow your curiosity')}</h3>{filters}</div><div class="margin-note">{tr('strong','这不是一本写完的书。','Not a finished book.')}{tr('p','算错的题、修过的电脑、做过的小东西，和一些还在想的问题。先诚实地记下来，再慢慢想清楚。','Wrong answers, repaired computers, small things I have made, and questions still open. An honest record, understood a little better over time.')}<a href="{link('garden-origin')}">{tr('span','关于这座小花园','About this little garden')} ↗</a></div></aside></div></section>
<section class="section lab" id="lab"><div class="lab-layout"><div class="lab-intro"><span class="label">03 / A SMALL INTERACTIVE NOTE</span>{tr('h2','有些公式，动手试更明白。','Some ideas are clearer when you try them.')}{tr('p','从一个最简单的电路开始。拖动电压和电阻，看看电流与功率怎样变化。这是这座网站里的一枚小实验。','Start with a simple circuit. Adjust voltage and resistance to see how current and power change—a small interactive note built for this site.')}<p class="formula" aria-hidden="true">I = U / R</p><a class="text-link" href="{link('engineering-study')}">{tr('span','再读一篇关于“真的弄懂”的手记','Read a note on really understanding')} ↗</a></div><div class="circuit-panel">{CIRCUIT}<div class="circuit-controls"><div><label class="control-head" for="voltage">{tr('span','电压 U','Voltage U')}<output id="voltage-value" for="voltage">12 V</output></label><input id="voltage" type="range" min="1" max="24" step="1" value="12"></div><div><label class="control-head" for="resistance">{tr('span','电阻 R','Resistance R')}<output id="resistance-value" for="resistance">200 Ω</output></label><input id="resistance" type="range" min="20" max="500" step="10" value="200"></div></div><div class="circuit-results" aria-live="polite"><div>{tr('small','电流 I','Current I')}<strong id="current-value">60.0 mA</strong></div><div>{tr('small','功率 P','Power P')}<strong id="power-value">0.720 W</strong></div></div><div class="current-meter" aria-hidden="true"><span id="current-meter"></span></div>{tr('p','理想电阻示意 · 改变一个变量，观察另一个。','An ideal resistor · Change one variable and observe another.','class="lab-caption"')}</div></div></section>
<section class="section" id="about"><div class="now-about"><div class="about-block"><span class="label">04 / THE PERSON BEHIND THE NOTES</span>{tr('h2','还在学，也还在试。','Still learning. Still trying.')}{tr('p',data['site']['about']['zh'],data['site']['about']['en'])}{tr('p','我不想把“正在学”包装成“精通”。比起一张漂亮的技能清单，我更想留下：一道题怎样想通，一个点子怎样落地，哪里做错了，下次怎么试。','I do not want to dress up learning as mastery. I would rather show how a question became clear, how an idea became real, what went wrong, and what I will try next.')}<a class="text-link" href="{link('my-path')}">{tr('span','我现在在学什么','What I am learning')} ↗</a><p class="signature">Young, still figuring things out.</p></div><div class="now-block" id="now"><span class="label">A SMALL NOW PAGE</span>{tr('h2','此刻，留在纸上的关注。','What has my attention.')}<a class="now-item" href="{link('my-path')}">{tr('strong','学习，回到基本功','Learning, back to the basics')}{tr('small','数学、电路、控制。把“好像懂了”变成能自己解释、自己动手。','Math, circuits and control. From recognition to explaining and doing it myself.')}</a><a class="now-item" href="{link('ai-workflow')}">{tr('strong','AI，拿来做一点东西','Using AI to make something')}{tr('small','从想法到能打开的网站，也认真核对它说得对不对。','From an idea to a website you can open, while checking what the model gets wrong.')}</a><a class="now-item" href="{link('study-rhythm')}">{tr('strong','生活，留一点空白','Life, with room to breathe')}{tr('small','课本、跑鞋、电影和 F1。学习之外，也好好过日子。','Textbooks, running shoes, films and F1. A life beyond studying.')}</a><p class="now-date">{tr('span','依据最近公开手记整理','From the latest published notes')} / {latest.replace('-','.')}</p></div></div></section>
<section class="contact" id="contact"><div class="contact-inner"><div><span class="label">A LETTER IS ALWAYS WELCOME</span>{tr('h2','如果你也有一点好奇。','If you are curious, too.')}{tr('p','学工程、玩 AI，或者有一个想一起折腾的小点子，都可以聊。你可以从一篇手记里的问题开始，也可以只说声你好。','Engineering, AI, or a small idea to try together—I would be happy to talk. Start with a question from a note, or just say hello.')}</div><a class="button" href="mailto:{e(data['site']['contact']['zh'])}">{tr('span','写封邮件给我','Write me a letter')} ↗</a></div><div class="contact-links"><a href="mailto:{e(data['site']['contact']['zh'])}">{e(data['site']['contact']['zh'])}</a><a href="https://github.com/YOUNG7788-WEB" target="_blank" rel="noopener noreferrer">GitHub ↗</a><a href="https://young7788-web.github.io/feed.xml">RSS ↗</a><a href="/lite.html">{tr('span','省流阅读','Text-only index')} ↗</a></div></section></main><footer class="shell"><span>© 2026 Young</span>{tr('span','在工程与好奇心之间，慢慢生长。','Growing slowly, between engineering and curiosity.','class="footer-note"')}<a href="#home" class="footer-top">{tr('span','回到页首','Back to top')} ↑</a></footer><script>{js}</script></body></html>'''
